import json, re

def parse_packages(filename):
    with open(filename) as f:
        content = f.read()
    # Find all JSON objects in the file
    results = {}
    decoder = json.JSONDecoder()
    pos = 0
    while pos < len(content):
        try:
            obj, end = decoder.raw_decode(content, pos)
            # Process this object
            if 'projects' in obj:
                for proj in obj['projects']:
                    path = proj.get('path','')
                    name = path.split('/')[-1] if '/' in path else path
                    frameworks = proj.get('frameworks', [])
                    for fw in frameworks:
                        for pkg in fw.get('topLevelPackages', []):
                            key = (name, pkg['id'])
                            results[key] = (pkg.get('requestedVersion',''), pkg.get('resolvedVersion',''))
            pos = end
        except json.JSONDecodeError:
            pos += 1
    return results

